"""Goal GC guard table own_a_063 (PNC-019 C12-GC Method B; generated by scripts/pm-goal-gc-guard-tables.py --generate).

One owner predicate per row, in the complete checker's evaluation order. Every row of this table is
evaluated by exactly the same accepted complete calls. Predicates read only their own derived observation;
the checker derives each observation from the complete input and decides nothing itself.
"""
import pm_guard_isolation as g

FIELDS = ('read_withdrawal', 'read_row', 'read_frontier',)


def R01_read_withdrawal(value, context):
    return 'read/withdrawal' if value['read_withdrawal'] is not True else None


def R02_read_row(value, context):
    return 'read/row' if value['read_row'] is not True else None


def R03_read_frontier(value, context):
    return 'read/frontier' if value['read_frontier'] is not True else None


def case(value):
    context = None
    table = g.GuardTable([
        g.Guard('R01_read_withdrawal', g.Invariant('/read_withdrawal', 'owner predicate read/withdrawal at scripts/pm_goal_own_a_oracles.py:865'), 'read/withdrawal', R01_read_withdrawal),
        g.Guard('R02_read_row', g.Invariant('/read_row', 'owner predicate read/row at scripts/pm_goal_own_a_oracles.py:871'), 'read/row', R02_read_row),
        g.Guard('R03_read_frontier', g.Invariant('/read_frontier', 'owner predicate read/frontier at scripts/pm_goal_own_a_oracles.py:872'), 'read/frontier', R03_read_frontier),
    ])

    def check(value):
        table.require('R01_read_withdrawal', value, context)
        table.require('R02_read_row', value, context)
        table.require('R03_read_frontier', value, context)
        return True
    return g.Case(table, check, context)
